CREATE EXTENSION IF NOT EXISTS pgcrypto;
DO $$ BEGIN IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname='arewa_app') THEN CREATE ROLE arewa_app LOGIN; END IF; END $$;
CREATE SCHEMA IF NOT EXISTS civic;
REVOKE ALL ON SCHEMA civic FROM PUBLIC;
GRANT USAGE ON SCHEMA civic TO arewa_app;
ALTER DEFAULT PRIVILEGES IN SCHEMA civic REVOKE EXECUTE ON FUNCTIONS FROM PUBLIC;
CREATE TABLE IF NOT EXISTS civic.accounts(id text PRIMARY KEY, email text UNIQUE NOT NULL, password_hash text NOT NULL, display_name text NOT NULL);
CREATE TABLE IF NOT EXISTS civic.memberships(user_id text PRIMARY KEY REFERENCES civic.accounts(id), workspace_id text NOT NULL DEFAULT 'ws-evaluation', role text NOT NULL CHECK(role IN ('ADMIN','MEAL','FOCAL_PERSON')), active boolean NOT NULL DEFAULT true, lga_ids text[] NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS civic.sessions(token_hash text PRIMARY KEY, user_id text NOT NULL REFERENCES civic.accounts(id), expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS civic.recovery(token_hash text PRIMARY KEY, user_id text NOT NULL REFERENCES civic.accounts(id), expires_at timestamptz NOT NULL, used boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS civic.reference_data(id text PRIMARY KEY, kind text NOT NULL CHECK(kind IN ('lga','sector')), data jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS civic.items(id text PRIMARY KEY, workspace_id text NOT NULL DEFAULT 'ws-evaluation', data jsonb NOT NULL, lga_id text GENERATED ALWAYS AS (data->>'lgaId') STORED REFERENCES civic.reference_data(id), CHECK(data->>'type' IN ('PUBLIC_PROJECT','SERVICE_ISSUE')));
CREATE TABLE IF NOT EXISTS civic.reports(id text PRIMARY KEY, workspace_id text NOT NULL DEFAULT 'ws-evaluation', data jsonb NOT NULL, item_id text GENERATED ALWAYS AS (data->>'itemId') STORED REFERENCES civic.items(id), author_id text GENERATED ALWAYS AS (data->>'authorId') STORED REFERENCES civic.accounts(id), CHECK(data->>'reviewState' IN ('DRAFT','SUBMITTED','IN_REVIEW','NEEDS_CLARIFICATION','VERIFIED','APPROVED','REJECTED')));
CREATE TABLE IF NOT EXISTS civic.revisions(id text PRIMARY KEY, report_id text NOT NULL REFERENCES civic.reports(id), data jsonb NOT NULL, UNIQUE(report_id, id));
CREATE TABLE IF NOT EXISTS civic.evidence(id text PRIMARY KEY, owner_id text NOT NULL REFERENCES civic.accounts(id), report_id text REFERENCES civic.reports(id), data jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS civic.revision_evidence(revision_id text NOT NULL REFERENCES civic.revisions(id), evidence_id text NOT NULL REFERENCES civic.evidence(id), PRIMARY KEY(revision_id,evidence_id));
CREATE TABLE IF NOT EXISTS civic.messages(id text PRIMARY KEY, report_id text NOT NULL REFERENCES civic.reports(id), data jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS civic.review_events(id text PRIMARY KEY, report_id text NOT NULL REFERENCES civic.reports(id), revision_id text NOT NULL REFERENCES civic.revisions(id), data jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS civic.actions(id text PRIMARY KEY, item_id text NOT NULL REFERENCES civic.items(id), data jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS civic.audit(id text PRIMARY KEY, workspace_id text NOT NULL DEFAULT 'ws-evaluation', data jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS civic.notifications(id text PRIMARY KEY, user_id text NOT NULL REFERENCES civic.accounts(id), data jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS civic.idempotency(user_id text NOT NULL, operation text NOT NULL, key text NOT NULL, payload_hash text NOT NULL, result jsonb NOT NULL, PRIMARY KEY(user_id,operation,key));
CREATE INDEX IF NOT EXISTS report_author_idx ON civic.reports(author_id);
CREATE INDEX IF NOT EXISTS report_item_idx ON civic.reports(item_id);
CREATE INDEX IF NOT EXISTS report_submitted_idx ON civic.reports((data->>'firstSubmittedAt'));
CREATE INDEX IF NOT EXISTS report_state_idx ON civic.reports((data->>'reviewState'));
CREATE INDEX IF NOT EXISTS revision_report_idx ON civic.revisions(report_id);
CREATE INDEX IF NOT EXISTS item_lga_idx ON civic.items(lga_id);
CREATE OR REPLACE FUNCTION civic.actor() RETURNS civic.memberships LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,civic AS $$ SELECT m FROM civic.memberships m JOIN civic.sessions s ON s.user_id=m.user_id WHERE s.token_hash=current_setting('civic.session',true) AND s.expires_at>now() AND m.active $$;
CREATE OR REPLACE FUNCTION civic.require_actor() RETURNS civic.memberships LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,civic AS $$ DECLARE m civic.memberships; BEGIN m:=civic.actor(); IF m.user_id IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED' USING ERRCODE='P0001'; END IF; RETURN m; END $$;
CREATE OR REPLACE FUNCTION civic.can_report(p_id text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,civic AS $$ SELECT EXISTS(SELECT 1 FROM civic.reports r JOIN civic.items i ON i.id=r.item_id CROSS JOIN civic.actor() m WHERE r.id=p_id AND m.user_id IS NOT NULL AND r.workspace_id=m.workspace_id AND (m.role='ADMIN' OR (m.role='MEAL' AND i.lga_id=ANY(m.lga_ids)) OR r.author_id=m.user_id)) $$;
CREATE OR REPLACE FUNCTION civic.can_item(p_id text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,civic AS $$ SELECT EXISTS(SELECT 1 FROM civic.items i CROSS JOIN civic.actor() m WHERE i.id=p_id AND m.user_id IS NOT NULL AND i.workspace_id=m.workspace_id AND (m.role='ADMIN' OR (i.lga_id=ANY(m.lga_ids) AND (m.role='MEAL' OR NOT coalesce((i.data->>'provisional')::boolean,true))) OR EXISTS(SELECT 1 FROM civic.reports r WHERE r.item_id=i.id AND r.author_id=m.user_id))) $$;
CREATE OR REPLACE FUNCTION civic.log_event(p_action text,p_id text,p_meta jsonb DEFAULT '{}'::jsonb) RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,civic AS $$ INSERT INTO civic.audit VALUES(gen_random_uuid()::text,(civic.require_actor()).workspace_id,jsonb_build_object('id',gen_random_uuid(),'actorId',(civic.require_actor()).user_id,'action',p_action,'entityId',p_id,'createdAt',now(),'metadata',p_meta)) $$;
CREATE OR REPLACE FUNCTION civic.immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'IMMUTABLE_RECORD'; END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['revisions','review_events','audit','revision_evidence'] LOOP IF NOT EXISTS(SELECT FROM pg_trigger WHERE tgname=t||'_immutable') THEN EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE OR DELETE ON civic.%I FOR EACH ROW EXECUTE FUNCTION civic.immutable()',t||'_immutable',t); END IF; END LOOP; END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['memberships','reference_data','items','reports','revisions','evidence','revision_evidence','messages','review_events','actions','audit','notifications'] LOOP EXECUTE format('ALTER TABLE civic.%I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('GRANT SELECT ON civic.%I TO arewa_app',t); END LOOP; END $$;
CREATE POLICY member_read ON civic.memberships FOR SELECT TO arewa_app USING (user_id=(civic.actor()).user_id OR ((civic.actor()).role='ADMIN' AND workspace_id=(civic.actor()).workspace_id));
CREATE POLICY reference_read ON civic.reference_data FOR SELECT TO arewa_app USING ((civic.actor()).user_id IS NOT NULL);
CREATE POLICY item_read ON civic.items FOR SELECT TO arewa_app USING(civic.can_item(id));
CREATE POLICY report_read ON civic.reports FOR SELECT TO arewa_app USING(civic.can_report(id));
CREATE POLICY revision_read ON civic.revisions FOR SELECT TO arewa_app USING(civic.can_report(report_id));
CREATE POLICY evidence_read ON civic.evidence FOR SELECT TO arewa_app USING(owner_id=(civic.actor()).user_id OR civic.can_report(report_id));
CREATE POLICY revision_evidence_read ON civic.revision_evidence FOR SELECT TO arewa_app USING(EXISTS(SELECT FROM civic.revisions r WHERE r.id=revision_id AND civic.can_report(r.report_id)));
CREATE POLICY message_read ON civic.messages FOR SELECT TO arewa_app USING(civic.can_report(report_id) AND (data->>'visibility'='AUTHOR' OR (civic.actor()).role IN ('MEAL','ADMIN')));
CREATE POLICY event_read ON civic.review_events FOR SELECT TO arewa_app USING(civic.can_report(report_id));
CREATE POLICY action_read ON civic.actions FOR SELECT TO arewa_app USING(civic.can_item(item_id) AND ((civic.actor()).role IN ('ADMIN','MEAL') OR data->>'visibility'='AUTHOR'));
CREATE POLICY audit_read ON civic.audit FOR SELECT TO arewa_app USING((civic.actor()).role='ADMIN' AND workspace_id=(civic.actor()).workspace_id);
CREATE POLICY notification_read ON civic.notifications FOR SELECT TO arewa_app USING(user_id=(civic.actor()).user_id);
CREATE OR REPLACE FUNCTION civic.profile() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,civic AS $$ SELECT jsonb_build_object('id',a.id,'displayName',a.display_name,'email',a.email,'role',m.role,'lgaIds',m.lga_ids,'workspaceId',m.workspace_id) FROM civic.accounts a JOIN civic.require_actor() m ON a.id=m.user_id $$;
CREATE OR REPLACE FUNCTION civic.sign_in(p_email text,p_password text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,civic,public AS $$ DECLARE a civic.accounts; m civic.memberships; tok text; BEGIN SELECT * INTO a FROM civic.accounts WHERE lower(email)=lower(p_email); IF a.id IS NULL OR a.password_hash<>public.crypt(p_password,a.password_hash) THEN RAISE EXCEPTION 'INVALID_CREDENTIALS'; END IF; SELECT * INTO m FROM civic.memberships WHERE user_id=a.id AND active; IF m.user_id IS NULL THEN RAISE EXCEPTION 'INVALID_CREDENTIALS'; END IF; tok:=encode(public.gen_random_bytes(32),'hex'); INSERT INTO civic.sessions VALUES(encode(public.digest(tok,'sha256'),'hex'),a.id,now()+interval '8 hours'); PERFORM set_config('civic.session',encode(public.digest(tok,'sha256'),'hex'),true); PERFORM civic.log_event('LOGIN',a.id); RETURN jsonb_build_object('token',tok,'user',civic.profile()); END $$;
CREATE OR REPLACE FUNCTION civic.sign_out() RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,civic AS $$ DELETE FROM civic.sessions WHERE token_hash=current_setting('civic.session',true) $$;
CREATE OR REPLACE FUNCTION civic.request_recovery(p_email text) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,civic,public AS $$ DECLARE uid text; tok text; BEGIN SELECT a.id INTO uid FROM civic.accounts a JOIN civic.memberships m ON m.user_id=a.id WHERE lower(a.email)=lower(p_email) AND m.active; IF uid IS NULL THEN RETURN NULL; END IF; tok:=encode(public.gen_random_bytes(32),'hex'); INSERT INTO civic.recovery VALUES(encode(public.digest(tok,'sha256'),'hex'),uid,now()+interval '30 minutes',false); RETURN tok; END $$;
CREATE OR REPLACE FUNCTION civic.reset_password(p_token text,p_password text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,civic,public AS $$ DECLARE r civic.recovery; BEGIN SELECT * INTO r FROM civic.recovery WHERE token_hash=encode(public.digest(p_token,'sha256'),'hex') AND NOT used AND expires_at>now() FOR UPDATE; IF r.user_id IS NULL OR length(p_password)<12 OR length(p_password)>128 THEN RAISE EXCEPTION 'RECOVERY_INVALID'; END IF; UPDATE civic.accounts SET password_hash=public.crypt(p_password,public.gen_salt('bf',10)) WHERE id=r.user_id; UPDATE civic.recovery SET used=true WHERE user_id=r.user_id; DELETE FROM civic.sessions WHERE user_id=r.user_id; END $$;
CREATE OR REPLACE FUNCTION civic.assert_payload(b jsonb) RETURNS void LANGUAGE plpgsql STABLE SET search_path=pg_catalog,civic AS $$ DECLARE typ text:=b->>'itemType'; dt date; BEGIN IF typ NOT IN ('PUBLIC_PROJECT','SERVICE_ISSUE') OR typ IS NULL OR length(trim(coalesce(b->>'title','')))<8 OR length(b->>'title')>150 OR length(trim(coalesce(b->>'community','')))<2 OR length(b->>'community')>150 OR length(trim(coalesce(b->>'observation','')))<20 OR length(b->>'observation')>5000 THEN RAISE EXCEPTION 'VALIDATION_ERROR'; END IF; IF NOT EXISTS(SELECT FROM civic.reference_data WHERE id=b->>'lgaId' AND kind='lga') OR NOT EXISTS(SELECT FROM civic.reference_data WHERE id=b->>'sectorId' AND kind='sector' AND coalesce((data->>'active')::boolean,true)) THEN RAISE EXCEPTION 'VALIDATION_ERROR'; END IF; IF coalesce(b->>'observationDate','') !~ '^\d{4}-\d{2}-\d{2}$' THEN RAISE EXCEPTION 'VALIDATION_ERROR'; END IF; BEGIN dt:=(b->>'observationDate')::date; EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'VALIDATION_ERROR'; END; IF dt>(now() AT TIME ZONE 'Africa/Lagos')::date THEN RAISE EXCEPTION 'FUTURE_DATE'; END IF; IF (typ='PUBLIC_PROJECT' AND coalesce(b->>'observedProgress','') NOT IN ('NOT_CONFIRMED','NOT_STARTED','IN_PROGRESS','STALLED','COMPLETED')) OR (typ='SERVICE_ISSUE' AND coalesce(b->>'observedProgress','') NOT IN ('NOT_CONFIRMED','OPEN','ACTION_IN_PROGRESS','RESOLVED','REOPENED')) THEN RAISE EXCEPTION 'INVALID_PROGRESS'; END IF; IF b ? 'coordinates' AND b->'coordinates'<>'null'::jsonb AND (NOT ((b->'coordinates'->>'latitude')::numeric BETWEEN -90 AND 90) OR NOT ((b->'coordinates'->>'longitude')::numeric BETWEEN -180 AND 180) OR b->'coordinates'->>'latitude' IS NULL OR b->'coordinates'->>'longitude' IS NULL) THEN RAISE EXCEPTION 'INVALID_LOCATION'; END IF; END $$;
CREATE OR REPLACE FUNCTION civic.submit_report(b jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,civic,public AS $$
DECLARE m civic.memberships:=civic.require_actor(); rid text:=gen_random_uuid()::text; iid text; vid text:=gen_random_uuid()::text; ref text; item jsonb; rev jsonb; rep jsonb; result jsonb; k text:=b->>'clientRecordId'; ph text:=encode(public.digest(b::text,'sha256'),'hex'); prior civic.idempotency; eid text; n integer;
BEGIN
 IF m.role NOT IN ('ADMIN','FOCAL_PERSON') THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
 IF m.role='FOCAL_PERSON' AND NOT coalesce(b->>'lgaId'=ANY(m.lga_ids),false) THEN RAISE EXCEPTION 'ASSIGNMENT_REQUIRED'; END IF;
 IF k IS NULL OR length(k)>120 THEN RAISE EXCEPTION 'IDEMPOTENCY_REQUIRED'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(m.user_id||k,0));
 SELECT * INTO prior FROM civic.idempotency WHERE user_id=m.user_id AND operation='submit' AND key=k;
 IF prior.key IS NOT NULL THEN IF prior.payload_hash<>ph THEN RAISE EXCEPTION 'IDEMPOTENCY_CONFLICT'; END IF; RETURN prior.result; END IF;
 PERFORM civic.assert_payload(b);
 IF b->>'itemId' IS NOT NULL AND b->>'itemId'<>'' THEN SELECT data INTO item FROM civic.items WHERE id=b->>'itemId' AND civic.can_item(id) FOR UPDATE; IF item IS NULL THEN RAISE EXCEPTION 'NOT_FOUND'; END IF; IF item->>'lgaId'<>b->>'lgaId' OR item->>'sectorId'<>b->>'sectorId' OR item->>'type'<>b->>'itemType' THEN RAISE EXCEPTION 'ITEM_MISMATCH'; END IF; iid:=item->>'id'; ELSE iid:=gen_random_uuid()::text; item:=jsonb_build_object('id',iid,'reference','ITEM-'||upper(left(iid,8)),'type',b->>'itemType','title',trim(b->>'title'),'sectorId',b->>'sectorId','lgaId',b->>'lgaId','community',trim(b->>'community'),'locationDescription',b->>'locationDescription','coordinates',b->'coordinates','provisional',true,'confirmedProgress','NOT_CONFIRMED','version',1,'createdAt',now()); INSERT INTO civic.items VALUES(iid,m.workspace_id,item); END IF;
 ref:='RPT-'||upper(left(rid,8));
 rep:=jsonb_build_object('id',rid,'reference',ref,'itemId',iid,'authorId',m.user_id,'clientRecordId',k,'reviewState','SUBMITTED','version',1,'currentRevisionId',vid,'createdAt',now(),'firstSubmittedAt',now(),'lastSubmittedAt',now());
 rev:=(b - 'attachments' - 'clientRecordId' - 'evidenceIds')||jsonb_build_object('id',vid,'reportId',rid,'revisionNumber',1,'observedDate',b->>'observationDate','submittedAt',now(),'submittedBy',m.user_id);
 INSERT INTO civic.reports VALUES(rid,m.workspace_id,rep); INSERT INTO civic.revisions VALUES(vid,rid,rev);
 n:=jsonb_array_length(coalesce(b->'evidenceIds','[]'::jsonb)); IF n>5 THEN RAISE EXCEPTION 'EVIDENCE_LIMIT'; END IF;
 FOR eid IN SELECT jsonb_array_elements_text(coalesce(b->'evidenceIds','[]'::jsonb)) LOOP
  PERFORM 1 FROM civic.evidence WHERE id=eid AND owner_id=m.user_id AND report_id IS NULL AND data->>'state'='READY' FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'EVIDENCE_NOT_READY'; END IF;
  UPDATE civic.evidence SET report_id=rid WHERE id=eid; INSERT INTO civic.revision_evidence VALUES(vid,eid);
 END LOOP;
 INSERT INTO civic.review_events VALUES(gen_random_uuid()::text,rid,vid,jsonb_build_object('reportId',rid,'revisionId',vid,'from','DRAFT','to','SUBMITTED','actorId',m.user_id,'reason','Field submission','createdAt',now()));
 PERFORM civic.log_event('SUBMIT_REPORT',rid);
 INSERT INTO civic.notifications SELECT gen_random_uuid()::text,user_id,jsonb_build_object('type','REPORT_RECEIVED','reportId',rid,'createdAt',now(),'read',false) FROM civic.memberships WHERE active AND workspace_id=m.workspace_id AND (role='ADMIN' OR (role='MEAL' AND b->>'lgaId'=ANY(lga_ids)));
 result:=jsonb_build_object('report',rep,'receipt',jsonb_build_object('reference',ref,'receivedAt',now())); INSERT INTO civic.idempotency VALUES(m.user_id,'submit',k,ph,result); RETURN result;
END $$;
CREATE OR REPLACE FUNCTION civic.review_report(p_id text,b jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,civic AS $$
DECLARE m civic.memberships:=civic.require_actor(); r civic.reports; st text:=b->>'state'; prev text; allowed text[];
BEGIN
 IF m.role NOT IN ('MEAL','ADMIN') THEN RAISE EXCEPTION 'REVIEWER_REQUIRED'; END IF;
 SELECT * INTO r FROM civic.reports WHERE id=p_id AND civic.can_report(id) FOR UPDATE; IF r.id IS NULL THEN RAISE EXCEPTION 'NOT_FOUND'; END IF;
 IF r.author_id=m.user_id THEN RAISE EXCEPTION 'SELF_REVIEW'; END IF;
 IF b->>'revisionId' IS DISTINCT FROM r.data->>'currentRevisionId' OR (b->>'version')::integer IS DISTINCT FROM (r.data->>'version')::integer THEN RAISE EXCEPTION 'VERSION_CONFLICT'; END IF;
 prev:=r.data->>'reviewState';
 allowed:=CASE prev WHEN 'SUBMITTED' THEN ARRAY['IN_REVIEW'] WHEN 'IN_REVIEW' THEN ARRAY['NEEDS_CLARIFICATION','VERIFIED','REJECTED'] WHEN 'VERIFIED' THEN ARRAY['APPROVED','NEEDS_CLARIFICATION','REJECTED'] WHEN 'APPROVED' THEN ARRAY['NEEDS_CLARIFICATION'] WHEN 'REJECTED' THEN ARRAY['NEEDS_CLARIFICATION'] ELSE ARRAY[]::text[] END;
 IF NOT coalesce(st=ANY(allowed),false) THEN RAISE EXCEPTION 'INVALID_TRANSITION'; END IF;
 IF (st='APPROVED' OR prev IN ('VERIFIED','APPROVED','REJECTED')) AND m.role<>'ADMIN' THEN RAISE EXCEPTION 'ADMIN_REQUIRED'; END IF;
 IF length(trim(coalesce(b->>'reason','')))<3 OR length(b->>'reason')>2000 THEN RAISE EXCEPTION 'REASON_REQUIRED'; END IF;
 r.data:=r.data||jsonb_build_object('reviewState',st,'version',(r.data->>'version')::integer+1);
 UPDATE civic.reports SET data=r.data WHERE id=p_id;
 INSERT INTO civic.review_events VALUES(gen_random_uuid()::text,p_id,r.data->>'currentRevisionId',jsonb_build_object('reportId',p_id,'revisionId',r.data->>'currentRevisionId','from',prev,'to',st,'actorId',m.user_id,'reason',b->>'reason','createdAt',now()));
 IF st='NEEDS_CLARIFICATION' THEN INSERT INTO civic.messages VALUES(gen_random_uuid()::text,p_id,jsonb_build_object('text',b->>'reason','visibility','AUTHOR','revisionId',r.data->>'currentRevisionId','createdAt',now())); END IF;
 IF st='APPROVED' THEN UPDATE civic.items SET data=data||'{"provisional":false}'::jsonb WHERE id=r.item_id; END IF;
 INSERT INTO civic.notifications VALUES(gen_random_uuid()::text,r.author_id,jsonb_build_object('type','REPORT_'||st,'reportId',p_id,'createdAt',now(),'read',false));
 PERFORM civic.log_event('REVIEW_'||st,p_id,jsonb_build_object('revisionId',r.data->>'currentRevisionId')); RETURN r.data;
END $$;
CREATE OR REPLACE FUNCTION civic.respond_report(p_id text,b jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,civic,public AS $$
DECLARE m civic.memberships:=civic.require_actor(); r civic.reports; old jsonb; rev jsonb; vid text:=gen_random_uuid()::text; k text:=b->>'operationId'; ph text:=encode(public.digest(b::text,'sha256'),'hex'); prior civic.idempotency;
BEGIN
 IF k IS NULL THEN RAISE EXCEPTION 'IDEMPOTENCY_REQUIRED'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(m.user_id||k,0));
 SELECT * INTO r FROM civic.reports WHERE id=p_id AND author_id=m.user_id FOR UPDATE; IF r.id IS NULL THEN RAISE EXCEPTION 'NOT_FOUND'; END IF;
 IF m.role='FOCAL_PERSON' AND NOT (SELECT lga_id=ANY(m.lga_ids) FROM civic.items WHERE id=r.item_id) THEN RAISE EXCEPTION 'ASSIGNMENT_REQUIRED'; END IF;
 SELECT * INTO prior FROM civic.idempotency WHERE user_id=m.user_id AND operation='respond' AND key=k; IF prior.key IS NOT NULL THEN IF prior.payload_hash<>ph THEN RAISE EXCEPTION 'IDEMPOTENCY_CONFLICT'; END IF; RETURN prior.result; END IF;
 IF b->>'revisionId' IS DISTINCT FROM r.data->>'currentRevisionId' OR (b->>'version')::integer IS DISTINCT FROM (r.data->>'version')::integer THEN RAISE EXCEPTION 'VERSION_CONFLICT'; END IF;
 IF r.data->>'reviewState'<>'NEEDS_CLARIFICATION' THEN RAISE EXCEPTION 'RESPOND_NOT_ALLOWED'; END IF;
 IF length(trim(coalesce(b->>'observation','')))<20 OR length(b->>'observation')>5000 THEN RAISE EXCEPTION 'VALIDATION_ERROR'; END IF;
 SELECT data INTO old FROM civic.revisions WHERE id=r.data->>'currentRevisionId';
 rev:=old||jsonb_build_object('id',vid,'revisionNumber',(old->>'revisionNumber')::integer+1,'observation',b->>'observation','submittedAt',now(),'submittedBy',m.user_id);
 INSERT INTO civic.revisions VALUES(vid,p_id,rev); INSERT INTO civic.revision_evidence SELECT vid,evidence_id FROM civic.revision_evidence WHERE revision_id=r.data->>'currentRevisionId';
 r.data:=r.data||jsonb_build_object('currentRevisionId',vid,'version',(r.data->>'version')::integer+1,'reviewState','SUBMITTED','lastSubmittedAt',now()); UPDATE civic.reports SET data=r.data WHERE id=p_id;
 INSERT INTO civic.review_events VALUES(gen_random_uuid()::text,p_id,vid,jsonb_build_object('from','NEEDS_CLARIFICATION','to','SUBMITTED','revisionId',vid,'reason','Clarification response','createdAt',now()));
 INSERT INTO civic.messages VALUES(gen_random_uuid()::text,p_id,jsonb_build_object('text',b->>'response','visibility','AUTHOR','revisionId',vid,'createdAt',now()));
 PERFORM civic.log_event('RESPOND_REPORT',p_id); INSERT INTO civic.idempotency VALUES(m.user_id,'respond',k,ph,r.data); RETURN r.data;
END $$;
CREATE OR REPLACE FUNCTION civic.add_message(p_id text,b jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,civic AS $$ DECLARE m civic.memberships:=civic.require_actor(); BEGIN IF NOT civic.can_report(p_id) THEN RAISE EXCEPTION 'NOT_FOUND'; END IF; IF length(trim(coalesce(b->>'text','')))<1 OR length(b->>'text')>2000 THEN RAISE EXCEPTION 'MESSAGE_REQUIRED'; END IF; INSERT INTO civic.messages VALUES(gen_random_uuid()::text,p_id,jsonb_build_object('text',b->>'text','visibility',CASE WHEN m.role='FOCAL_PERSON' THEN 'AUTHOR' WHEN b->>'visibility'='INTERNAL' THEN 'INTERNAL' ELSE 'AUTHOR' END,'createdAt',now(),'authorId',m.user_id)); PERFORM civic.log_event('ADD_MESSAGE',p_id); END $$;
CREATE OR REPLACE FUNCTION civic.register_evidence(p_id text,b jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,civic AS $$ DECLARE m civic.memberships:=civic.require_actor(); prior civic.evidence; BEGIN IF m.role NOT IN ('ADMIN','FOCAL_PERSON') THEN RAISE EXCEPTION 'FORBIDDEN'; END IF; SELECT * INTO prior FROM civic.evidence WHERE id=p_id; IF prior.id IS NOT NULL THEN IF prior.owner_id<>m.user_id OR prior.data->>'checksum'<>b->>'checksum' THEN RAISE EXCEPTION 'IDEMPOTENCY_CONFLICT'; END IF; RETURN prior.data; END IF; INSERT INTO civic.evidence VALUES(p_id,m.user_id,NULL,b||jsonb_build_object('id',p_id,'state','READY','createdAt',now())); RETURN b||jsonb_build_object('id',p_id,'state','READY'); END $$;
CREATE OR REPLACE FUNCTION civic.confirm_progress(p_id text,b jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,civic AS $$ DECLARE m civic.memberships:=civic.require_actor(); i civic.items; r civic.reports; s text:=b->>'progress'; BEGIN IF m.role<>'ADMIN' THEN RAISE EXCEPTION 'ADMIN_REQUIRED'; END IF; SELECT * INTO i FROM civic.items WHERE id=p_id AND workspace_id=m.workspace_id FOR UPDATE; SELECT * INTO r FROM civic.reports WHERE id=b->>'sourceReportId' AND item_id=p_id FOR UPDATE; IF i.id IS NULL OR r.id IS NULL OR r.data->>'reviewState'<>'APPROVED' THEN RAISE EXCEPTION 'APPROVED_SOURCE_REQUIRED'; END IF; IF b->>'revisionId' IS DISTINCT FROM r.data->>'currentRevisionId' OR (b->>'version')::integer IS DISTINCT FROM (i.data->>'version')::integer THEN RAISE EXCEPTION 'VERSION_CONFLICT'; END IF; IF (i.data->>'type'='PUBLIC_PROJECT' AND coalesce(s,'') NOT IN ('NOT_CONFIRMED','NOT_STARTED','IN_PROGRESS','STALLED','COMPLETED')) OR (i.data->>'type'='SERVICE_ISSUE' AND coalesce(s,'') NOT IN ('NOT_CONFIRMED','OPEN','ACTION_IN_PROGRESS','RESOLVED','REOPENED')) OR length(trim(coalesce(b->>'reason','')))<3 THEN RAISE EXCEPTION 'INVALID_PROGRESS'; END IF; i.data:=i.data||jsonb_build_object('confirmedProgress',s,'confirmedRevisionId',r.data->>'currentRevisionId','version',(i.data->>'version')::integer+1); UPDATE civic.items SET data=i.data WHERE id=p_id; INSERT INTO civic.actions VALUES(gen_random_uuid()::text,p_id,jsonb_build_object('action','Progress confirmed: '||s,'reason',b->>'reason','sourceReportId',r.id,'revisionId',r.data->>'currentRevisionId','createdAt',now(),'visibility','AUTHOR')); PERFORM civic.log_event('CONFIRM_PROGRESS',p_id); RETURN i.data; END $$;
CREATE OR REPLACE FUNCTION civic.manage_user(p_id text,b jsonb,p_password text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,civic,public AS $$ DECLARE m civic.memberships:=civic.require_actor(); target civic.memberships; rid text:=coalesce(p_id,gen_random_uuid()::text); role_new text; active_new boolean; BEGIN IF m.role<>'ADMIN' THEN RAISE EXCEPTION 'ADMIN_REQUIRED'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended('memberships:'||m.workspace_id,0)); IF p_id IS NULL THEN IF length(coalesce(p_password,''))<12 OR coalesce(b->>'email','') !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' OR length(trim(coalesce(b->>'displayName','')))<2 THEN RAISE EXCEPTION 'INVALID_USER'; END IF; INSERT INTO civic.accounts VALUES(rid,lower(b->>'email'),public.crypt(p_password,public.gen_salt('bf',10)),b->>'displayName'); INSERT INTO civic.memberships VALUES(rid,m.workspace_id,coalesce(b->>'role','FOCAL_PERSON'),true,'{}'); END IF; SELECT * INTO target FROM civic.memberships WHERE user_id=rid AND workspace_id=m.workspace_id FOR UPDATE; IF target.user_id IS NULL THEN RAISE EXCEPTION 'NOT_FOUND'; END IF; role_new:=coalesce(b->>'role',target.role); active_new:=coalesce((b->>'active')::boolean,target.active); IF target.role='ADMIN' AND target.active AND (role_new<>'ADMIN' OR NOT active_new) AND (SELECT count(*) FROM civic.memberships WHERE workspace_id=m.workspace_id AND role='ADMIN' AND active)<=1 THEN RAISE EXCEPTION 'LAST_ADMIN'; END IF; IF b ? 'lgaIds' AND EXISTS(SELECT FROM jsonb_array_elements_text(b->'lgaIds') x WHERE NOT EXISTS(SELECT FROM civic.reference_data WHERE id=x AND kind='lga')) THEN RAISE EXCEPTION 'INVALID_ASSIGNMENT'; END IF; UPDATE civic.memberships SET role=role_new,active=active_new,lga_ids=CASE WHEN b ? 'lgaIds' THEN ARRAY(SELECT jsonb_array_elements_text(b->'lgaIds')) ELSE lga_ids END WHERE user_id=rid; PERFORM civic.log_event('MANAGE_USER',rid,b-'email'-'displayName'); RETURN jsonb_build_object('id',rid,'role',role_new,'active',active_new); END $$;
CREATE OR REPLACE FUNCTION civic.list_users() RETURNS SETOF jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,civic AS $$ DECLARE m civic.memberships:=civic.require_actor(); BEGIN IF m.role<>'ADMIN' THEN RAISE EXCEPTION 'ADMIN_REQUIRED'; END IF; RETURN QUERY SELECT jsonb_build_object('id',a.id,'email',a.email,'displayName',a.display_name,'role',x.role,'active',x.active,'lgaIds',x.lga_ids) FROM civic.accounts a JOIN civic.memberships x ON x.user_id=a.id WHERE x.workspace_id=m.workspace_id ORDER BY a.display_name; END $$;
CREATE OR REPLACE FUNCTION civic.mark_notification(p_id text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,civic AS $$ BEGIN UPDATE civic.notifications SET data=data||'{"read":true}'::jsonb WHERE id=p_id AND user_id=(civic.require_actor()).user_id; END $$;
CREATE OR REPLACE FUNCTION civic.save_action(p_id text,b jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,civic AS $$ DECLARE m civic.memberships:=civic.require_actor(); BEGIN IF m.role NOT IN ('ADMIN','MEAL') OR NOT civic.can_item(p_id) THEN RAISE EXCEPTION 'FORBIDDEN'; END IF; IF length(trim(coalesce(b->>'action','')))<3 OR b->>'status' NOT IN ('OPEN','IN_PROGRESS','DONE') THEN RAISE EXCEPTION 'VALIDATION_ERROR'; END IF; INSERT INTO civic.actions VALUES(gen_random_uuid()::text,p_id,b||jsonb_build_object('createdAt',now(),'actorId',m.user_id,'visibility','AUTHOR')); PERFORM civic.log_event('RECORD_ACTION',p_id); END $$;
CREATE OR REPLACE FUNCTION civic.save_reference(p_id text,b jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,civic AS $$ BEGIN IF (civic.require_actor()).role<>'ADMIN' THEN RAISE EXCEPTION 'ADMIN_REQUIRED'; END IF; IF length(trim(coalesce(b->>'label','')))<2 THEN RAISE EXCEPTION 'VALIDATION_ERROR'; END IF; INSERT INTO civic.reference_data VALUES(p_id,'sector',b||jsonb_build_object('id',p_id)) ON CONFLICT(id) DO UPDATE SET data=civic.reference_data.data||b; PERFORM civic.log_event('REFERENCE_UPDATED',p_id); END $$;
GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA civic TO arewa_app;
REVOKE EXECUTE ON FUNCTION civic.immutable(),civic.log_event(text,text,jsonb),civic.assert_payload(jsonb) FROM arewa_app;
CREATE TABLE IF NOT EXISTS civic.schema_migrations(version text PRIMARY KEY, applied_at timestamptz DEFAULT now());
INSERT INTO civic.schema_migrations(version) VALUES('001_core') ON CONFLICT DO NOTHING;
CREATE OR REPLACE FUNCTION civic.record_export(p_format text,p_filters jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,civic AS $$ BEGIN PERFORM civic.log_event('EXPORT_'||p_format,NULL,p_filters); END $$;
GRANT EXECUTE ON FUNCTION civic.record_export(text,jsonb) TO arewa_app;
